/**
 * Publish the verified plugin bundle on the `release` branch.
 *
 * main carries only source: the bundle and build.json are build outputs, regenerated by
 * every source change, so committing them made every pair of PRs conflict. The Claude Code
 * marketplace serves plugin/ from `release` instead (.claude-plugin/marketplace.json).
 *
 * Each release adds one commit to `release`. Its tree is the tag's tree plus the two
 * built files, taken from the skill archive the release workflow has already verified
 * (nothing is rebuilt). Its parents are the previous `release` head and the tag, so the
 * branch only ever fast-forwards (no force) and every released source commit is reachable.
 *
 *   bun .github/scripts/release-branch.ts <release-dir> <release-promotion.json> <tag> [--push]
 */
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { unzip } from '../../src/update/apply.ts';
import { git } from '../../src/util/exec.ts';

/** The only paths a release commit may add to the tag's tree. */
export const BUILT = [
  'plugin/skills/tracetoon/build.json',
  'plugin/skills/tracetoon/dist/tracetoon.mjs',
] as const;

const IDENTITY = {
  GIT_AUTHOR_NAME: 'github-actions[bot]',
  GIT_AUTHOR_EMAIL: '41898282+github-actions[bot]@users.noreply.github.com',
  GIT_COMMITTER_NAME: 'github-actions[bot]',
  GIT_COMMITTER_EMAIL: '41898282+github-actions[bot]@users.noreply.github.com',
};

function must(repo: string, args: string[], env?: NodeJS.ProcessEnv): string {
  const r = git(repo, args, undefined, env);
  if (!r.ok) throw new Error(`git ${args.join(' ')} failed: ${r.stderr.trim()}`);
  return r.stdout.trim();
}

export interface ReleaseCommit {
  /** The commit to push to `release`, or the existing head when it already has this release. */
  commit: string;
  created: boolean;
}

/**
 * Build the `release` commit for `tag` from the verified skill archive. `previous` is the
 * current `release` head, if the branch exists. Nothing in the working tree changes.
 */
export function releaseCommit(opts: {
  repo: string;
  zip: string;
  tag: string;
  version: string;
  buildId: string;
  previous?: string;
}): ReleaseCommit {
  const { repo, tag, version, buildId, previous } = opts;
  const source = must(repo, ['rev-parse', '--verify', `${tag}^{commit}`]);
  const tagVersion = must(repo, ['show', `${source}:plugin/skills/tracetoon/VERSION`]);
  if (tagVersion !== version)
    throw new Error(`${tag} carries VERSION ${tagVersion}, not ${version}.`);

  const work = mkdtempSync(join(tmpdir(), 'tracetoon-release-branch-'));
  try {
    unzip(opts.zip, work);
    const skill = join(work, 'tracetoon');
    const zipVersion = readFileSync(join(skill, 'VERSION'), 'utf8').trim();
    if (zipVersion !== version)
      throw new Error(`The skill archive is ${zipVersion}, not ${version}.`);
    const zipBuild = JSON.parse(readFileSync(join(skill, 'build.json'), 'utf8')).buildId;
    if (zipBuild !== buildId)
      throw new Error(`The skill archive is build ${zipBuild}, not the promoted ${buildId}.`);

    // A private index: start from the tag's tree, add the built files, write the tree.
    const env = { ...process.env, GIT_INDEX_FILE: join(work, 'index') };
    must(repo, ['read-tree', source], env);
    for (const path of BUILT) {
      const file = join(skill, path.slice('plugin/skills/tracetoon/'.length));
      const blob = must(repo, ['hash-object', '-w', '--', file]);
      must(repo, ['update-index', '--add', '--cacheinfo', `100644,${blob},${path}`], env);
    }
    const tree = must(repo, ['write-tree'], env);

    const changed = must(repo, ['diff-tree', '-r', '--name-only', source, tree])
      .split('\n')
      .filter(Boolean)
      .sort();
    if (JSON.stringify(changed) !== JSON.stringify([...BUILT].sort()))
      throw new Error(
        `A release commit may only add ${BUILT.join(' and ')}; this one changes: ${changed.join(', ') || 'nothing'}.`,
      );

    // Re-running the workflow for a release that is already on the branch is a no-op.
    if (previous && must(repo, ['rev-parse', `${previous}^{tree}`]) === tree)
      return { commit: previous, created: false };

    const parents = previous ? ['-p', previous, '-p', source] : ['-p', source];
    const commit = must(
      repo,
      [
        'commit-tree',
        tree,
        ...parents,
        '-m',
        `Release ${tag}: plugin bundle\n\nThe verified ${tag} build of plugin/skills/tracetoon on top of the tagged source.`,
      ],
      { ...process.env, ...IDENTITY },
    );
    return { commit, created: true };
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

if (import.meta.main) {
  const [dir, promotionFile, tag] = process.argv.slice(2);
  if (!dir || !promotionFile || !tag)
    throw new Error(
      'usage: release-branch.ts <release-dir> <release-promotion.json> <tag> [--push]',
    );
  const repo = process.cwd();
  const promotion = JSON.parse(readFileSync(promotionFile, 'utf8'));
  // The branch may not exist yet (the first release creates it).
  const fetched = git(repo, ['fetch', 'origin', '+refs/heads/release:refs/remotes/origin/release']);
  const previous = fetched.ok ? must(repo, ['rev-parse', 'refs/remotes/origin/release']) : undefined;
  const result = releaseCommit({
    repo,
    zip: join(dir, 'tracetoon-skill.zip'),
    tag,
    version: promotion.version,
    buildId: promotion.buildId,
    previous,
  });
  console.log(
    result.created
      ? `release: ${result.commit} (${tag} on top of ${previous ?? 'nothing'})`
      : `release: already at ${tag} (${result.commit})`,
  );
  if (process.argv.includes('--push') && result.created)
    must(repo, ['push', 'origin', `${result.commit}:refs/heads/release`]);
}
